/** Uses only public JEI 19.27 APIs. Category-local rectangles are rebuilt for each document. */
public final class CompatJeiLayouts {
    public record BoundRegion(String id,String binding,Rect2i rect){}
    public record Source(IRecipeCategory<?> category,boolean holder,Object original){}
    public record Slot(Rect2i rect,RecipeIngredientRole role,String name,boolean fluid,boolean item,List<String> ingredients){}
    public record View(IRecipeLayoutDrawable<?> layout,List<Slot> slots,String error){public int width(){return layout==null?260:Math.max(1,layout.getRecipeCategory().getWidth());}public int height(){return layout==null?160:Math.max(1,layout.getRecipeCategory().getHeight());}}
    private static final Map<String,Source> sources=new HashMap<>();
    private record Preferred(String category,String nativeType,boolean recoverable){}
    private static final Map<String,Preferred> preferred=new HashMap<>();
    public static void clear(){sources.clear();}
    public static void reset(){clear();preferred.clear();}
    public static View update(View before){if(before.layout==null)return before;var slots=new ArrayList<Slot>();for(var slot:before.layout.getRecipeSlotsView().getSlotViews())if(slot instanceof IRecipeSlotDrawable drawable)try{var r=drawable.getRect();if(r.getWidth()>0&&r.getHeight()>0)slots.add(new Slot(new Rect2i(r.getX(),r.getY(),r.getWidth(),r.getHeight()),slot.getRole(),slot.getSlotName().orElse(""),slot.getAllIngredients().anyMatch(v->v.getIngredient() instanceof FluidStack),slot.getAllIngredients().anyMatch(v->v.getIngredient() instanceof ItemStack),CompatIngredients.signatures(slot.getAllIngredients().map(v->v.getIngredient()).toList())));}catch(RuntimeException ignored){}return geometry(before.slots).equals(geometry(slots))?before:new View(before.layout,List.copyOf(slots),before.error);}
    private static String geometry(List<Slot> slots){return slots.stream().map(s->s.role+":"+s.name+":"+s.item+":"+s.fluid+":"+s.rect.getX()+","+s.rect.getY()+","+s.rect.getWidth()+","+s.rect.getHeight()+":"+s.ingredients).toList().toString();}
    @SuppressWarnings({"rawtypes","unchecked"}) public static IRecipeLayoutDrawable<?> reference(IRecipeLayoutDrawable<?> layout){var copy=WorkspaceJeiPlugin.runtime.getRecipeManager().createRecipeLayoutDrawable((IRecipeCategory)layout.getRecipeCategory(),layout.getRecipe(),WorkspaceJeiPlugin.runtime.getJeiHelpers().getFocusFactory().getEmptyFocusGroup()).orElseThrow();((IRecipeLayoutDrawable<?>)copy).setPosition(0,0);return (IRecipeLayoutDrawable<?>)copy;}
    public static void remember(String id,IRecipeLayoutDrawable<?> layout){sources.put(id,new Source(layout.getRecipeCategory(),layout.getRecipe() instanceof RecipeHolder<?>,layout.getRecipe()));var mc=Minecraft.getInstance();if(mc.level!=null){var manager=mc.hasSingleplayerServer()?mc.getSingleplayerServer().getRecipeManager():mc.level.getRecipeManager();manager.byKey(ResourceLocation.parse(id)).ifPresent(holder->{String type=BuiltInRegistries.RECIPE_SERIALIZER.getKey(holder.value().getSerializer()).toString(),category=layout.getRecipeCategory().getRecipeType().getUid().toString();Object shown=layout.getRecipe() instanceof RecipeHolder<?> h?h.value():layout.getRecipe();preferred.put(id,new Preferred(category,type,shown.getClass()==holder.value().getClass()||ConvertedRecipeSources.supports(category,type)));});}}
    @SuppressWarnings({"rawtypes","unchecked"}) public static void locate(String id){
        if(sources.containsKey(id)||WorkspaceJeiPlugin.runtime==null)return;var manager=WorkspaceJeiPlugin.runtime.getRecipeManager();
        var local=Minecraft.getInstance();if(local.level!=null&&local.level.getRecipeManager().byKey(ResourceLocation.parse(id)).isEmpty()&&(local.getSingleplayerServer()==null||local.getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse(id)).isEmpty()))return;
        var nativeManager=local.hasSingleplayerServer()?local.getSingleplayerServer().getRecipeManager():local.level.getRecipeManager();var nativeHolder=nativeManager.byKey(ResourceLocation.parse(id));var preference=preferred.get(id);
        if(preference!=null&&preference.recoverable&&nativeHolder.isPresent()&&preference.nativeType.equals(BuiltInRegistries.RECIPE_SERIALIZER.getKey(nativeHolder.get().value().getSerializer()).toString())){var category=manager.createRecipeCategoryLookup().includeHidden().get().filter(c->c.getRecipeType().getUid().toString().equals(preference.category)).findFirst();if(category.isPresent()){boolean holder=category.get().getRecipeType().getRecipeClass().isInstance(nativeHolder.get());Object original=holder?nativeHolder.get():nativeHolder.get().value();if(category.get().getRecipeType().getRecipeClass().isInstance(original)){sources.put(id,new Source(category.get(),holder,original));return;}}}
        for(IRecipeCategory category:manager.createRecipeCategoryLookup().get().toList())for(Object recipe:(List<?>)manager.createRecipeLookup(category.getRecipeType()).get().toList()){
            if(recipe instanceof RecipeHolder<?> holder&&!holder.id().toString().equals(id))continue;
            if(!(recipe instanceof RecipeHolder<?>)&&!(recipe instanceof Recipe<?>))continue;
            if(recipe instanceof Recipe<?> nativeRecipe){var mc=Minecraft.getInstance();var server=mc.getSingleplayerServer();boolean serverMatch=server!=null&&server.getRecipeManager().byKey(ResourceLocation.parse(id)).map(h->h.value()==nativeRecipe).orElse(false);boolean clientMatch=mc.level!=null&&mc.level.getRecipeManager().byKey(ResourceLocation.parse(id)).map(h->h.value()==nativeRecipe).orElse(false);if(!serverMatch&&!clientMatch)continue;}
            var layout=manager.createRecipeLayoutDrawable(category,recipe,WorkspaceJeiPlugin.runtime.getJeiHelpers().getFocusFactory().getEmptyFocusGroup());if(layout.isPresent()){var l=(IRecipeLayoutDrawable<?>)layout.get();var source=JeiRecipeSources.resolve(l);if(source.id()!=null&&source.id().toString().equals(id)){remember(id,l);return;}}
        }
    }
    @SuppressWarnings({"rawtypes","unchecked"}) public static View create(String id,JsonObject data){try{
        boolean registryEntry=dev.kubejseditor.model.RegistryEntryTarget.isId(id);
        if(registryEntry){Object value=RegistryDataSources.decode(RegistryDataSources.target(id),data);var original=sources.get(id);var choice=WorkspaceJeiPlugin.runtime.getRecipeManager().createRecipeCategoryLookup().includeHidden().get().filter(c->c.getRecipeType().getRecipeClass().isInstance(value)).toList();var category=choice.stream().filter(c->original!=null&&c.getRecipeType().getUid().equals(original.category.getRecipeType().getUid())).findFirst().or(()->choice.stream().findFirst());if(category.isPresent())sources.put(id,new Source(category.get(),false,value));}
        else locate(id);var source=sources.get(id);if(source==null)return new View(null,List.of(),"JEI 没有可重建的分类布局；可用字段编辑");
        if(CompatDefinitions.isRitual(data.get("type").getAsString())){
            String resultType=CompatJson.get(data,"/result/type").getAsString();String categoryClass="com.stal111.forbidden_arcanus.common.integration.hephaestus_forge."+(resultType.equals("forbidden_arcanus:upgrade_tier")?"UpgradeTierCategory":"SmithingCategory");
            var preferred=WorkspaceJeiPlugin.runtime.getRecipeManager().createRecipeCategoryLookup().includeHidden().get().filter(c->c.getClass().getName().equals(categoryClass)).findFirst();if(preferred.isPresent())source=new Source(preferred.get(),false,source.original);
        }
        var mc=Minecraft.getInstance();var displayData=ConvertedRecipeSources.preview(source.category.getRecipeType().getUid().toString(),data);Object nativeRecipe;if(registryEntry)nativeRecipe=RegistryDataSources.decode(RegistryDataSources.target(id),data);else{var serializer=BuiltInRegistries.RECIPE_SERIALIZER.get(ResourceLocation.parse(displayData.get("type").getAsString()));var ops=mc.getSingleplayerServer().registryAccess().createSerializationContext(JsonOps.INSTANCE);nativeRecipe=serializer.codec().codec().parse(ops,displayData).getOrThrow();}Object wrapped=source.holder?new RecipeHolder(ResourceLocation.parse(id),(Recipe)nativeRecipe):nativeRecipe;
        String diagnostic=null;if(!source.category.getRecipeType().getRecipeClass().isInstance(wrapped)){wrapped=source.original;diagnostic="原始 JEI 参考预览：自定义展示对象不能自动重建，修改值见右侧字段";}
        var manager=WorkspaceJeiPlugin.runtime.getRecipeManager();IRecipeLayoutDrawable<?> layout=(IRecipeLayoutDrawable<?>)manager.createRecipeLayoutDrawable((IRecipeCategory)source.category,wrapped,WorkspaceJeiPlugin.runtime.getJeiHelpers().getFocusFactory().getEmptyFocusGroup()).orElseThrow();layout.setPosition(0,0);var slots=new ArrayList<Slot>();
        for(var view:layout.getRecipeSlotsView().getSlotViews()){if(!(view instanceof IRecipeSlotDrawable drawable))continue;try{Rect2i rect=drawable.getRect();if(rect.getWidth()<1||rect.getHeight()<1)continue;slots.add(new Slot(new Rect2i(rect.getX(),rect.getY(),rect.getWidth(),rect.getHeight()),view.getRole(),view.getSlotName().orElse(""),view.getAllIngredients().anyMatch(v->v.getIngredient() instanceof FluidStack),view.getAllIngredients().anyMatch(v->v.getIngredient() instanceof ItemStack),CompatIngredients.signatures(view.getAllIngredients().map(v->v.getIngredient()).toList())));}catch(RuntimeException ignored){/* Purely custom widgets can be annotated manually. */}}
        return new View(layout,List.copyOf(slots),diagnostic);
    }catch(Throwable e){CompatDiagnostics.failure("layout",id,e);return new View(null,List.of(),"布局创建失败，草稿保留："+e.getClass().getSimpleName()+" "+e.getMessage());}}
    public static Map<String,Rect2i> bind(String id,View view,RecipePresentation presentation){var result=new LinkedHashMap<String,Rect2i>();var bindings=presentation.bindings().stream().filter(b->(b.field().slot()||b.field().role==Role.RESOURCE)&&b.field().readOnlyReason.isBlank()&&!presentation.nativeValue(b).isJsonNull()).toList();var used=new HashSet<String>();var reserved=new ArrayList<Rect2i>();try{var profile=readProfile(id,view,presentation.data);if(profile!=null)for(var r:profile.regions)if(bindings.stream().anyMatch(b->b.key().equals(r.binding))){result.put(r.binding,new Rect2i(r.x,r.y,r.width,r.height));used.add(r.binding);reserved.add(new Rect2i(r.x,r.y,r.width,r.height));}}catch(Exception ignored){}boolean known=Set.of("modern_industrialization","forbidden_arcanus","ars_nouveau").contains(presentation.definition.source);
        var ordered=new ArrayList<>(bindings);if(presentation.definition.source.equals("ars_nouveau")||presentation.definition.source.equals("forbidden_arcanus"))ordered.sort(Comparator.comparingInt(b->b.field().role==Role.CENTER?0:1));
        for(var slot:view.slots){if(reserved.stream().anyMatch(r->sameRect(r,slot.rect)))continue;var candidates=ordered.stream().filter(b->!used.contains(b.key())&&matches(b,slot)).toList();RecipePresentation.Binding match=null;
            if(!slot.name.isBlank()){var named=candidates.stream().filter(b->slot.name.equals(b.field().path.substring(b.field().path.lastIndexOf('/')+1))||slot.name.equals(b.key())||slot.name.equals(b.path())).toList();if(named.size()==1)match=named.getFirst();}
            if(match==null&&known&&!candidates.isEmpty())match=candidates.getFirst();
            if(match==null&&!slot.ingredients.isEmpty()){var exact=candidates.stream().filter(b->!ambiguousQuantity(view,presentation,b,slot)&&slot.ingredients.equals(CompatIngredients.binding(presentation,b))).toList();if(exact.size()==1)match=exact.getFirst();else if(!exact.isEmpty()){var first=exact.getFirst();boolean equivalent=exact.stream().allMatch(b->b.field().role==first.field().role&&b.field().quantity.equals(first.field().quantity)&&b.field().probability.equals(first.field().probability)&&CompatJson.equal(presentation.nativeValue(b),presentation.nativeValue(first)));if(equivalent)match=first;}}
            if(match==null&&!slot.ingredients.isEmpty()){var sameIdentity=candidates.stream().filter(b->{var signature=CompatIngredients.binding(presentation,b);return !ambiguousQuantity(view,presentation,b,slot)&&!signature.isEmpty()&&CompatIngredients.identities(signature).equals(CompatIngredients.identities(slot.ingredients));}).toList();if(sameIdentity.size()==1)match=sameIdentity.getFirst();else if(!sameIdentity.isEmpty()&&sameIdentity.stream().allMatch(b->CompatJson.equal(presentation.nativeValue(b),presentation.nativeValue(sameIdentity.getFirst()))))match=sameIdentity.getFirst();}
            if(match!=null){used.add(match.key());result.put(match.key(),slot.rect);}
        }
        if(view.error!=null&&view.error.startsWith("原始 JEI 参考预览"))try{var holder=Minecraft.getInstance().getSingleplayerServer().getRecipeManager().byKey(ResourceLocation.parse(id));var adapter=dev.kubejseditor.recipe.RecipeAdapters.get(presentation.definition.type);if(holder.isPresent()&&adapter!=null){var base=dev.kubejseditor.export.GenericFormatter.encodeRecipe(holder.get()).getAsJsonObject();base.addProperty("type",presentation.definition.type);if(CompatJson.shape(base).equals(CompatJson.shape(presentation.data))){var basePresentation=adapter.presentation(base);if(basePresentation!=null){var baseline=bind(id,new View(view.layout,view.slots,null),basePresentation);for(var e:baseline.entrySet())if(bindings.stream().anyMatch(b->b.key().equals(e.getKey())))result.put(e.getKey(),e.getValue());}}}}catch(RuntimeException ignored){}
        // These icons are drawn by the mod, not registered as JEI ingredient slots.
        // The profile is pinned to the inspected version/category; other custom widgets use marks.
        if(presentation.definition.source.equals("forbidden_arcanus")&&CompatibilityRecipes.modVersion(presentation.definition.type).equals("2.6.1")&&view.layout!=null&&Set.of("com.stal111.forbidden_arcanus.common.integration.hephaestus_forge.SmithingCategory","com.stal111.forbidden_arcanus.common.integration.hephaestus_forge.UpgradeTierCategory").contains(view.layout.getRecipeCategory().getClass().getName()))try{
            Class<?> info=Class.forName("com.stal111.forbidden_arcanus.common.integration.hephaestus_forge.EssenceInfo");
            Object entries=info.getMethod("create",mezz.jei.api.helpers.IGuiHelper.class,int.class,int.class).invoke(null,WorkspaceJeiPlugin.runtime.getJeiHelpers().getGuiHelper(),41,view.layout.getRecipeCategory().getClass().getSimpleName().equals("UpgradeTierCategory")?79:83);
            for(Object value:(List<?>)entries){String name=((Enum<?>)info.getMethod("type").invoke(value)).name().toLowerCase(Locale.ROOT);for(var b:presentation.bindings())if(b.path().equals("/essences/"+name))result.put(b.key(),new Rect2i((int)info.getMethod("posX").invoke(value),(int)info.getMethod("posY").invoke(value),12,12));}
            var tier=view.slots.stream().filter(s->s.role==RecipeIngredientRole.RENDER_ONLY&&s.item).findFirst();if(tier.isPresent())for(var b:presentation.bindings())if(b.path().equals("/forge_tier"))result.put(b.key(),tier.get().rect);
            if(view.layout.getRecipeCategory().getClass().getSimpleName().equals("UpgradeTierCategory")){var inputs=view.slots.stream().filter(s->s.role==RecipeIngredientRole.INPUT&&s.item).toList();if(!inputs.isEmpty())for(var b:presentation.bindings())if(b.path().equals("/forge_tier"))result.put(b.key(),inputs.getLast().rect);var target=view.slots.stream().filter(s->s.role==RecipeIngredientRole.OUTPUT&&s.item).findFirst();if(target.isPresent())for(var b:presentation.bindings())if(b.path().equals("/result/result_tier"))result.put(b.key(),target.get().rect);}
        }catch(ReflectiveOperationException|LinkageError ignored){/* Manual marking remains available. */}
        try{var profile=readProfile(id,view,presentation.data);if(profile!=null)for(var region:profile.regions)if(presentation.editableBindings().stream().anyMatch(b->b.key().equals(region.binding)))result.put(region.binding,new Rect2i(region.x,region.y,region.width,region.height));}catch(Exception ignored){}
        if(view.layout!=null&&view.error!=null&&view.error.startsWith("原始 JEI 参考预览"))for(var slot:view.layout.getRecipeSlotsView().getSlotViews())if(slot instanceof IRecipeSlotDrawable drawable)for(var e:result.entrySet())if(sameRect(drawable.getRect(),e.getValue())){var b=bindings.stream().filter(v->v.key().equals(e.getKey())).findFirst();if(b.isPresent()&&b.get().field().slot()){var values=CompatIngredients.values(presentation,b.get());if(!values.isEmpty())drawable.createDisplayOverrides().addIngredientsUnsafe(values);}}
        return result;
    }
    private static boolean ambiguousQuantity(View view,RecipePresentation p,RecipePresentation.Binding binding,Slot slot){var identity=CompatIngredients.identities(slot.ingredients);var group=p.bindings().stream().filter(b->b.field().slot()&&b.field().readOnlyReason.isBlank()&&matches(b,slot)&&CompatIngredients.identities(CompatIngredients.binding(p,b)).equals(identity)).toList();if(group.size()<2)return false;boolean equivalent=group.stream().allMatch(b->CompatJson.equal(p.nativeValue(b),p.nativeValue(group.getFirst())));var nativeValues=group.stream().map(b->CompatIngredients.binding(p,b).toString()).toList();var displayed=view.slots.stream().filter(s->s.role==slot.role&&CompatIngredients.identities(s.ingredients).equals(identity)).map(s->s.ingredients.toString()).toList();return QuantityMatching.ambiguous(nativeValues,displayed,equivalent);}
    public static List<BoundRegion> boundRegions(String id,View view,RecipePresentation p){var result=new ArrayList<BoundRegion>();bind(id,view,p).forEach((key,rect)->result.add(new BoundRegion("auto:"+key,key,rect)));try{var profile=readProfile(id,view,p.data);if(profile!=null){var valid=p.editableBindings().stream().map(RecipePresentation.Binding::key).collect(java.util.stream.Collectors.toSet());var manual=profile.regions.stream().filter(r->valid.contains(r.binding)).toList();var keys=manual.stream().map(r->r.binding).collect(java.util.stream.Collectors.toSet());result.removeIf(r->keys.contains(r.binding()));for(var r:manual)result.add(new BoundRegion(r.regionId(),r.binding,new Rect2i(r.x,r.y,r.width,r.height)));}}catch(Exception ignored){}return List.copyOf(result);}
    private static boolean matches(RecipePresentation.Binding b,Slot s){if(b.field().role==Role.RESOURCE)return s.role==RecipeIngredientRole.INPUT&&!s.item&&!s.fluid;boolean output=b.field().role==Role.OUTPUT,catalyst=b.field().role==Role.CATALYST;boolean role=catalyst?s.role==RecipeIngredientRole.CATALYST:output?s.role==RecipeIngredientRole.OUTPUT:s.role==RecipeIngredientRole.INPUT;return role&&(b.field().kind==Kind.OTHER?s.ingredients.stream().anyMatch(i->i.startsWith("other:"+b.field().ingredientType+":")):b.fluid()?s.fluid:s.item);}
    private static String shape(View view,JsonObject data){return CompatJson.shape(data)+"/"+view.slots.stream().map(s->s.role+":"+s.name+":"+s.rect.getX()+","+s.rect.getY()+","+s.rect.getWidth()+","+s.rect.getHeight()).toList();}
    private static Path file(){return EditorRuntime.root().resolve("kubejs/config/kubejs_editor/layout-mappings.json");}
    private static List<LayoutMappings.Profile> profiles()throws Exception{if(!Files.exists(file()))return new ArrayList<>();return new ArrayList<>(Arrays.asList(ProjectStore.JSON.fromJson(Files.readString(file()),LayoutMappings.Profile[].class)));}
    public static LayoutMappings.Profile readProfile(String id,View view,JsonObject data)throws Exception{String category=view.layout==null?"native:"+data.get("type").getAsString():view.layout.getRecipeCategory().getRecipeType().getUid().toString();return profiles().stream().filter(p->LayoutMappings.matches(p,category,CompatibilityRecipes.modVersion(data.get("type").getAsString()),shape(view,data),view.width(),view.height())).findFirst().orElse(null);}
    public static void mark(String id,View view,JsonObject data,String binding,Rect2i rect)throws Exception{var all=profiles();String category=view.layout==null?"native:"+data.get("type").getAsString():view.layout.getRecipeCategory().getRecipeType().getUid().toString();var p=readProfile(id,view,data);if(p==null){p=new LayoutMappings.Profile();p.category=category;p.modVersion=CompatibilityRecipes.modVersion(data.get("type").getAsString());p.shape=shape(view,data);p.width=view.width();p.height=view.height();}p.regions.removeIf(r->r.x==rect.getX()&&r.y==rect.getY()&&r.width==rect.getWidth()&&r.height==rect.getHeight());var added=new LayoutMappings.Region(binding,rect.getX(),rect.getY(),rect.getWidth(),rect.getHeight());added.id=UUID.randomUUID().toString();p.regions.add(added);LayoutMappings.check(p);var profile=p;all.removeIf(v->LayoutMappings.matches(v,profile.category,profile.modVersion,profile.shape,profile.width,profile.height));all.add(p);FileTransaction.atomicWrite(file(),ProjectStore.JSON.toJson(all).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    public static void clearMarks(String id,View view,JsonObject data)throws Exception{var profile=readProfile(id,view,data);if(profile==null)return;var all=profiles();all.removeIf(p->LayoutMappings.matches(p,profile.category,profile.modVersion,profile.shape,profile.width,profile.height));FileTransaction.atomicWrite(file(),ProjectStore.JSON.toJson(all).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
    public static List<RecipePresentation.Binding> candidates(RecipePresentation p,Slot slot){return p.editableBindings().stream().filter(b->b.field().slot()&&(matches(b,slot)||!slot.item&&!slot.fluid&&(b.output()?slot.role==RecipeIngredientRole.OUTPUT:b.field().role==Role.CATALYST?slot.role==RecipeIngredientRole.CATALYST:slot.role==RecipeIngredientRole.INPUT))).toList();}
    public static boolean sameRect(Rect2i a,Rect2i b){return a!=null&&b!=null&&a.getX()==b.getX()&&a.getY()==b.getY()&&a.getWidth()==b.getWidth()&&a.getHeight()==b.getHeight();}
    private CompatJeiLayouts(){}
}
